// Bubble Bell Adventure — starts on a deliberate player gesture.
let soundtrack=null,musicUnlocked=false,musicPending=false,musicBlocked=false;
function soundLabel(){const b=$('sound');b.classList.toggle('music-playing',audioOn&&musicUnlocked&&!musicBlocked&&!document.hidden);b.setAttribute('aria-pressed',String(audioOn));b.setAttribute('aria-label',audioOn?'Mute music and sound effects':'Enable music and sound effects');b.title='Bubble Bell Adventure · Music & effects';const label=b.querySelector('span');if(label)label.textContent=audioOn?(musicBlocked?'Tap for sound':'Sound on'):'Sound off';}
function unlockGameAudio(){if(!audioOn)return;musicUnlocked=true;musicBlocked=false;try{if(!soundtrack){soundtrack=new Audio();soundtrack.src='assets/bubble-bell-adventure.mp3';soundtrack.loop=true;soundtrack.preload='auto';soundtrack.volume=0;}if(soundtrack.paused&&!musicPending&&!document.hidden){musicPending=true;const play=soundtrack.play();Promise.resolve(play).then(()=>{musicPending=false;if(!audioOn||document.hidden)soundtrack.pause();soundLabel();}).catch(()=>{musicPending=false;musicBlocked=true;soundLabel();});}}catch{musicBlocked=true;}soundLabel();}
function toggleGameSound(){if(audioOn&&musicBlocked){unlockGameAudio();return;}audioOn=!audioOn;try{localStorage.setItem('sarah-sound-enabled',audioOn?'1':'0');}catch{}if(audioOn){unlockGameAudio();tone(740,.09,.035);}else if(soundtrack){soundtrack.pause();soundtrack.volume=0;}soundLabel();}
function updateMusic(dt){if(!soundtrack)return;if(!audioOn||document.hidden){if(!soundtrack.paused)soundtrack.pause();soundtrack.volume=0;return;}if(soundtrack.paused)return;let target=state==='dialogue'?.15:state==='paused'?.07:state==='ready'?.2:state==='portal'?.26:.32;const time=soundtrack.currentTime,duration=soundtrack.duration;if(Number.isFinite(duration)&&duration>2){target*=Math.min(1,time/.8,Math.max(0,(duration-time)/.7));}soundtrack.volume=Math.max(0,Math.min(1,soundtrack.volume+(target-soundtrack.volume)*(1-Math.exp(-Math.min(dt,.1)*3))));}
function initGameSound(){try{audioOn=localStorage.getItem('sarah-sound-enabled')!=='0';}catch{audioOn=true;}soundLabel();document.addEventListener('visibilitychange',()=>{if(document.hidden){if(soundtrack){soundtrack.pause();soundtrack.volume=0;}soundLabel();}else if(musicUnlocked&&audioOn)unlockGameAudio();});}
